private void updateValue(final METRIC metric) {
    // Check if the metric is already in the cache
    boolean inCache = isDataInCache(metric);
    if (inCache) {
        // Merge the data with the existing value
        METRICS dataToMerge = metric.equals(getCacheValue()) ? metric : metric.merge(getCacheValue());
        // Update the cache with the merged data
        put(dataToMerge);
    } else {
        // Add the data to the cache if it is not already present
        put(metric);
    }
}

private boolean isDataInCache(final METRIC data) {
    return getCacheValue().stream().anyMatch(metric -> metric.equals(data));
}

