private static String substituteVars(String value, Properties props) {
   Set<String> varNames = getVarNames(value);
   for (String varName : varNames) {
      String varValue = props.getProperty(varName);
      if (varValue != null) {
         value = value.replace("${" + varName + "}", varValue);
      }
   }
