}

private static Set<String> getVarNames(String value) {
   Pattern varPat = Pattern.compile("\\$\\{(.*?)\\}");
   Matcher matcher = varPat.matcher(value);
   Set<String> varNames = new HashSet<>();
   while (matcher.find()) {
      varNames.add(matcher.group(1));
   }
   return varNames;
}

