        // not a method descriptor, check if it's a type descriptor
        int index = descriptor.lastIndexOf(";[");
        if (index != -1) {
            // array descriptor, get the number of dimensions
            String numDims = descriptor.substring(index + 1, descriptor.length() - 1);
